internal sealed class ProductImageReferenceConfiguration : IEntityTypeConfiguration<ProductImageReference> { public void Configure(EntityTypeBuilder<ProductImageReference> b) { b.ToTable("product_image_references", CatalogPersistence.Schema, t => t.HasCheckConstraint("ck_product_images_reference", "media_id IS NOT NULL OR external_reference IS NOT NULL")); b.HasKey(x => x.Id); b.Property(x => x.Id).Id(x => x.Value, x => new ProductImageReferenceId(x)); b.Property(x => x.ProductId).Id(x => x.Value, x => new ProductId(x)); b.Property(x => x.MerchantId).HasColumnType("uuid"); b.Property(x => x.ExternalReference).HasMaxLength(2000); b.Property(x => x.AltText).HasMaxLength(500); b.Property(x => x.CreatedAtUtc).Utc(); b.HasIndex(x => x.ProductId).IsUnique().HasFilter("is_primary = true"); } }
internal sealed class ProductAvailabilityConfiguration : IEntityTypeConfiguration<ProductAvailabilitySchedule> { public void Configure(EntityTypeBuilder<ProductAvailabilitySchedule> b) { b.ToTable("product_availability_schedules"); b.HasKey(x => x.Id); b.Property(x => x.Id).Id(x => x.Value, x => new ProductAvailabilityScheduleId(x)); b.Property(x => x.ProductId).Id(x => x.Value, x => new ProductId(x)); b.Property(x => x.MerchantId).HasColumnType("uuid"); b.Property(x => x.MerchantBranchId).HasColumnType("uuid"); b.Property(x => x.DayOfWeek).HasConversion<short>(); b.Property(x => x.StartLocalTime).HasColumnType("time without time zone"); b.Property(x => x.EndLocalTime).HasColumnType("time without time zone"); b.Property(x => x.TimeZoneId).HasMaxLength(100); b.HasIndex(x => new { x.ProductId, x.MerchantBranchId, x.DayOfWeek }); } }
